def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    if n >= 100:
        return 'D'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = opp.count('C')
    opp_d = n - opp_c
    # If opponent never defected, keep cooperating but exploit near the end.
    if opp_d == 0:
        if n >= 95:
            return 'D'
        if n == 50:
            return 'D'
        return 'C'
    # Detect mostly-defecting opponent: defend hard.
    if opp_d >= n * 2 // 3 and n >= 6:
        # Occasional probe to restart cooperation if opponent softens.
        recent = opp[-6:]
        if recent.count('C') >= 3:
            return 'C'
        return 'D'
    last_opp = opp[-1]
    last_me = me[-1]
    # Punish a defection after our cooperation, but forgive quickly.
    if last_opp == 'D':
        if last_me == 'C':
            # one-round retaliation unless endgame
            if n >= 95:
                return 'D'
            # if opponent rarely defects, forgive once
            if opp_d <= max(1, n // 10) and n >= 8:
                return 'C'
            return 'D'
        # DD cycle: try to break out occasionally
        run_dd = 0
        for i in range(n - 1, -1, -1):
            if me[i] == 'D' and opp[i] == 'D':
                run_dd += 1
            else:
                break
        if run_dd >= 3 and rng.random() < 0.4:
            return 'C'
        if n >= 95:
            return 'D'
        return 'D'
    # Opponent just cooperated.
    if n >= 95:
        # Endgame: only deviate if opponent has been defecting a lot recently.
        if opp[-5:].count('D') >= 2:
            return 'D'
        return 'C'
    # If we defected last, return to cooperation to avoid punishment spirals.
    if last_me == 'D':
        return 'C'
    # Both cooperating: stay cooperative; exploit a confirmed always-cooperator rarely.
    if opp_d <= 1 and n >= 20:
        if n % 11 == 0:
            return 'D'
    # If opponent is mostly cooperative but occasionally tests us, keep cooperating.
    return 'C'
